  static IconData resolve(String name, {PhosphorIconStyle style = PhosphorIconStyle.regular}) {
    switch (style) {
      case PhosphorIconStyle.bold:
        return _resolveBold(name);
      case PhosphorIconStyle.fill:
        return _resolveFill(name);
      case PhosphorIconStyle.regular:
        return _resolveRegular(name);
    }
  }

